The violated invariant is block-wide barrier participation: every non-exited thread in the block must reach the same dynamic `__syncthreads()`. With 96 threads and `valid = 70`, threads 0–69 enter the conditional barrier while threads 70–95 skip it. That is invalid CUDA synchronization; it can explain the affected stream’s stalled completion, but it does not imply every device must hang, and successful immediate launch checks do not establish correct execution.

Move the barrier outside the conditional and initialize every shared-memory slot. This complete program supports every `valid` from 0 through 96:

```cuda
// sum.cu
#include <cuda_runtime.h>
#include <cerrno>
#include <cstdio>
#include <cstdlib>

#define CUDA_CHECK(call) do {                                      \
    cudaError_t err = (call);                                      \
    if (err != cudaSuccess) {                                     \
        std::fprintf(stderr, "%s: %s\n", #call,                   \
                     cudaGetErrorString(err));                    \
        std::exit(EXIT_FAILURE);                                  \
    }                                                             \
} while (0)

// Preconditions: exactly one block of 96 threads; 0 <= valid <= 96;
// input has at least valid readable elements; output has one element.
__global__ void sum_valid(const float* input, float* output, int valid) {
    __shared__ float values[96];
    const int t = static_cast<int>(threadIdx.x);

    // The conditional operator evaluates only the selected operand.
    values[t] = (t < valid) ? input[t] : 0.0f;
    __syncthreads();

    if (t == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i)
            sum += values[i];
        output[0] = sum;
    }
}

int main(int argc, char** argv) {
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        errno = 0;
        const long n = std::strtol(argv[1], &end, 10);
        if (errno != 0 || end == argv[1] || *end != '\0' ||
            n < 0 || n > 96) {
            std::fprintf(stderr, "valid must be an integer from 0 to 96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(n);
    }

    float input[96];
    for (int i = 0; i < 96; ++i)
        input[i] = static_cast<float>(i + 1);
    float result = -1.0f;
    float* d_input = nullptr;
    float* d_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    CUDA_CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CUDA_CHECK(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));
    CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&d_input), sizeof(input)));
    CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&d_output), sizeof(float)));
    CUDA_CHECK(cudaMemcpyAsync(d_input, input, sizeof(input),
                               cudaMemcpyHostToDevice, stream));

    sum_valid<<<1, 96, 0, stream>>>(d_input, d_output, valid);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaMemcpyAsync(&result, d_output, sizeof(float),
                               cudaMemcpyDeviceToHost, stream));
    CUDA_CHECK(cudaEventRecord(done, stream));
    CUDA_CHECK(cudaEventSynchronize(done));

    const float expected = static_cast<float>(valid * (valid + 1) / 2);
    std::printf("valid=%d sum=%g expected=%g\n", valid, result, expected);

    CUDA_CHECK(cudaFree(d_output));
    CUDA_CHECK(cudaFree(d_input));
    CUDA_CHECK(cudaEventDestroy(done));
    CUDA_CHECK(cudaStreamDestroy(stream));
    return result == expected ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

Compile with `nvcc sum.cu -o sum` and run `./sum 70`, `./sum 0`, or `./sum 96` on a CUDA-capable system.

Synchronization proof: each of the 96 threads writes a distinct, in-bounds shared-memory slot, and only threads with `t < valid` read input. Every thread then reaches the single unconditional barrier, which makes those writes visible to thread zero before it reads them. Thread zero alone writes the output; at `valid = 0` its loop performs no reads and writes zero, while at `valid = 96` it sums exactly slots 0–95. Stream ordering places the input copy before the kernel and the output copy after it; successful completion-event synchronization establishes that the host result is ready.
